const agent=$('ElevenLabs | Check Main Agent').first().json??{};
const main=String(agent.main_branch_id??'');
if(!main||String(agent.agent_id??'')!=='agent_6401m3yvs1rcfbya7hk1qb2bxp8v')throw new Error('AGENT_MAIN_UNVERIFIED');
const rows=$input.all().flatMap(x=>Array.isArray(x.json)?x.json:Array.isArray(x.json?.data)?x.json.data:[x.json]),seen=new Set();
return rows.filter(x=>/^conv_[A-Za-z0-9]+$/.test(String(x.conversation_id??'')))
.filter(x=>{if(seen.has(x.conversation_id))return false;seen.add(x.conversation_id);return true;})
.map(x=>({json:{...x,main_branch_id:main}}));

const results=$input.all(),pending=$('Select | Valid Pending Conversations').all();
if(results.length!==pending.length)throw new Error('CONVERSATION_LOOKUP_COUNT_MISMATCH');
const items=[],ts=x=>typeof x==='number'&&Number.isFinite(x)?new Date(x>1e12?x:x*1000).toISOString():null;
const number=x=>typeof x==='number'&&Number.isFinite(x)&&x>=0?x:null;
for(let i=0;i<results.length;i++){
 const d=results[i]?.json??{},p=pending[i]?.json??{},m=d.metadata??{},an=d.analysis??{};
 if(d.error||String(d.conversation_id??'')!==p.conversation_id)continue;
 if(d.agent_id!=='agent_6401m3yvs1rcfbya7hk1qb2bxp8v'||!p.main_branch_id||String(d.branch_id??'')!==p.main_branch_id)continue;
 const status=String(d.status??'').toLowerCase();if(!['done','failed'].includes(status))continue;
 const incoming=$('Validate | Official Event and Conversation').first().json;
 const providerFailure=incoming.kind==='call_initiation_failure'&&incoming.conversation_id===p.conversation_id?incoming.failure_reason:null;
 const reason=String(providerFailure??m.termination_reason??d.termination_reason??m.phone_call_status??m.call_status??'');
 const r=reason.toLowerCase(),turns=Array.isArray(d.transcript)?d.transcript.filter(t=>t.role==='user'&&String(t.message??'').trim()).length:0;
 const vars={},collected=an.data_collection_results??{};
 for(const [key,value] of Object.entries(collected)){vars[String(value?.name??key)]=value?.value??value??null;}
 const yes=k=>vars[k]===true||vars[k]==='true';
 let outcome='unknown',source='unrecognized_terminal';
 if(/declined the call permission|permission request rejected|permission denied/.test(r)){
  outcome='permission_declined';source='permission_denied_explicit';
 }else if(/call rejected by the user|user rejected the call|declined the incoming call/.test(r)){
  outcome='rejected';source='explicit_user_call_rejection';
 }else if(['no_answer','not_answered','unanswered','busy','no_pickup'].includes(r)||/no[- ]answer|not answered|no.pickup|unanswered|call missed|missed by the user|ringing timed out|busy/.test(r)){
  outcome='no_answer';source='explicit_no_answer_termination';
 }else if(turns>0){outcome='answered';source='transcript_user_turns';}
 items.push({json:{p_result:{
  conversation_id:p.conversation_id,agent_id:d.agent_id,branch_id:String(d.branch_id),main_branch_id:p.main_branch_id,
  conversation_status:status,outcome,classification_evidence:source,termination_reason:reason||null,user_turns:turns,
  started_at:ts(m.start_time_unix_secs),ended_at:ts(m.end_time_unix_secs),
  duration_seconds:number(m.call_duration_secs),
  credits_consumed:number(m.credits_consumed)??number(m.usage?.credits_consumed),
  summary:typeof an.transcript_summary==='string'?an.transcript_summary:null,
  meaningful:yes('information_delivered')&&turns>0,qualified:yes('qualified')&&turns>0,
  tour_requested:yes('school_tour_requested'),callback_requested:yes('callback_requested'),
  do_not_contact:yes('do_not_contact'),collected_variables:vars
 }}});
}
return items;

const b=$input.first().json?.body??{};
const envelope=b.event&&typeof b.event==='object'?b.event:b;
const cid=String(envelope.conversation_id??envelope.data?.conversation_id??'');
const kind=String(envelope.type??'post_call_transcription');
const id=String(envelope.data?.agent_id??'');
if(!/^conv_[A-Za-z0-9]+$/.test(cid))throw new Error('INVALID_CONVERSATION_ID');
if(!['post_call_transcription','call_initiation_failure'].includes(kind))throw new Error('UNSUPPORTED_POSTCALL_EVENT');
if(kind==='call_initiation_failure'&&id!=='agent_6401m3yvs1rcfbya7hk1qb2bxp8v')throw new Error('AGENT_MISMATCH');
const failure=kind==='call_initiation_failure'?String(envelope.data?.failure_reason??'').toLowerCase():null;
if(failure&&!['busy','no-answer','unknown'].includes(failure))throw new Error('UNSUPPORTED_FAILURE_REASON');
return [{json:{conversation_id:cid,kind,failure_reason:failure}}];

const done=$input.all().flatMap(x=>Array.isArray(x.json)?x.json:[x.json]);
let originals=[];try{originals=$('Classify | Confirmed Final Call').all().flatMap(x=>Array.isArray(x.json)?x.json:[x.json]);}catch{return [];}
if(!done.length||done.length!==originals.length)return [];
const events=[];
for(let i=0;i<originals.length;i++){
 const res=done[i],p=originals[i].p_result??{};
 if(res?.ok!==true||!/^conv_[A-Za-z0-9]+$/.test(String(p.conversation_id??'')))continue;
 let status=null;
 if(p.outcome==='permission_declined')status='Opted out';
 else if(p.outcome==='answered'&&Number(p.user_turns)>0){
  const t=Number(p.duration_seconds),reason=String(p.termination_reason??'').toLowerCase();
  const deliberate=/client disconnected|user (ended|hung up|disconnected)|call ended by user/.test(reason);
  status=deliberate&&Number.isFinite(t)&&t>0&&t<=35?'Colgó rápidamente':'Contestó';
 }
 else if((p.outcome==='no_answer'||p.outcome==='rejected')&&p.classification_evidence!=='unrecognized_terminal')status='Opted in · llamada iniciada';
 if(status)events.push({conversation_id:p.conversation_id,next_status:status});
}
return events.length?[{json:{events}}]:[];

const rows=$input.all().flatMap(x=>Array.isArray(x.json)?x.json:[x.json]).filter(x=>x.conversation_id);
const found=new Map(rows.map(x=>[x.conversation_id,x]));
let requested=[];try{requested=$('SOFIA07 | Preparar eventos').first().json.events??[];}catch{return []}
return requested.flatMap(x=>{
 const row=found.get(x.conversation_id);
 return row?.ghl_opportunity_id&&row?.ghl_contact_id?[{json:{opportunity_id:row.ghl_opportunity_id,contact_id:row.ghl_contact_id,next_status:x.next_status}}]:[];
});

const raw=$input.all(),req=$('SOFIA07 | Enlazar oportunidades').all();
if(raw.length!==req.length)return [];
const all=['Autorización solicitada','Opted out','Opted in · llamada iniciada','Contestó','Colgó rápidamente','Resultado claro'];
return req.flatMap((r,i)=>{
 const fields=raw[i]?.json?.customFields??raw[i]?.json?.data?.customFields??[];
 const field=Array.isArray(fields)?fields.find(f=>f.model==='opportunity'&&f.name==='SOFIA | Estado de atención IA') : null;
 return field?.id&&field.dataType==='SINGLE_OPTIONS'&&all.every(v=>(field.picklistOptions??[]).includes(v))?
 [{json:{...r.json,field_id:field.id}}]:[];
});

const results=$input.all(),req=$('SOFIA07 | Resolver campo').all();
if(results.length!==req.length)return [];
const weight={'Autorización solicitada':1,'Opted in · llamada iniciada':2,'Contestó':3,'Colgó rápidamente':4,'Resultado claro':5,'Opted out':6};
return req.flatMap((v,i)=>{
 const raw=results[i]?.json??{},o=raw.opportunity??raw,a=v.json;
 if(raw.error||Number(raw.statusCode)>=400||o.id!==a.opportunity_id||o.contactId!==a.contact_id||o.status!=='open')return [];
 const current=(o.customFields??[]).find(f=>f.id===a.field_id)?.fieldValue;
 if(typeof current==='string'&&(!weight[current]||weight[current]>=weight[a.next_status]))return [];
 return [{json:a}];
});
